#!/usr/bin/env python3
import os, re
REF = '/tmp/xztest/ref'

def cap(name, stream):
    p = os.path.join(REF, f'list_{name}.{stream}')
    data = open(p, 'rb').read().decode('utf-8')
    return data

def block(name, stream):
    d = cap(name, stream)
    if d == '':
        return 'empty\n'
    return d

TEMPLATE = open('/tmp/xzprobe_list/template.md').read()

def repl(m):
    name, stream = m.group(1), m.group(2)
    return block(name, stream)

out = re.sub(r'\{\{CAP:([a-z0-9_]+)\.(out|err)\}\}', repl, TEMPLATE)
open('/tmp/xztest/ref/sections/05_list.md', 'w').write(out)
print('written', len(out), 'bytes')
